from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('initial.mol',removeHs=False,sanitize=False)
x=np.array([list(map(float,line.split()[1:])) for line in open('optimized.xyz').readlines()[2:]])
for b in m.GetBonds():
 i=b.GetBeginAtomIdx();j=b.GetEndAtomIdx();d=np.linalg.norm(x[i]-x[j]);
 if d>2.0 and not (i==0 or j==0):print('LONG',i,j,m.GetAtomWithIdx(i).GetSymbol(),m.GetAtomWithIdx(j).GetSymbol(),b.GetBondType(),d)
 if d<0.75:print('SHORT',i,j,d)
print('total',len(x))
